head.script:
scwin.gIsurCd;
scwin.gSeq;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name getParentValue
 * @description get Parent Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParentValue = function() {
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !개선계획서--;
검색-- > async function() {
    const url_list = "/PenaltyImposition.do?method=listPerfmDtlFile&inputMessageId=DUTY_PERFM_DTL_INOUT" + "&outputMessageId=DUTY_PERFM_DTL_INOUT";
    const url_cond = "&ISUR_CD=" + scwin.gIsurCd;
    // 그리드의 데이타 조회
    const sbmOptions = {
        id : "sbm_dts_imprfile_list",
        action : "&SCREN_ID=",
        ref : "",
        target : "dts_imprfile_list=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name filedown
 * @description 개선계획서파일 다운로드
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(row) {
    const link = "/filedownload.do?" + "&ISUR_CD=" + dts_imprfile_list.getCellData(row, "ISUR_CD") + "&SEQ=" + dts_imprfile_list.getCellData(row, "SEQ") + "&gubun=60" + "&SCREN_ID=" + 'ULDSTF35118.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08;
    location.href = encodeURI(link);
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function(row) {
    const vAnswer = confirm('선택한 이행 내역을 삭제처리 하시겠습니까?');
    if (vAnswer === true) {
        dts_Pnlt_Input.insertRow();
        dts_Pnlt_Input.setCellData(1, "ISUR_CD", dts_imprfile_list.getCellData(row, "ISUR_CD"));
        dts_Pnlt_Input.setCellData(1, "SEQ", dts_imprfile_list.getCellData(row, "SEQ"));
        dts_Pnlt_Input.setCellData(1, "EMP_NO", js_emp_no);
        trs_Pnlt_Input.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Pnlt_Input",
            action : "/PenaltyImposition.do",
            ref : "dts_Pnlt_Input",
            target : "trs_Pnlt_Input=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name dts_imprfile_list_OnLoadCompleted
 * @description dts_imprfile_list 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_imprfile_list_OnLoadCompleted = function(rowcount) {
    txb_isur_cd.setValue(dts_imprfile_list.getCellData(1, "ISUR_CD"));
    txb_com_abbrv.setValue(dts_imprfile_list.getCellData(1, "COM_ABBRV"));
};

/**
 * @method
 * @name dts_imprfile_list_OnLoadError
 * @description dts_imprfile_list 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_imprfile_list_OnLoadError = async function() {
    await $c.win.alert(dts_imprfile_list);
};

/**
 * @method
 * @name grd_imprfile_list_OnDblClick
 * @description grd_imprfile_list 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_imprfile_list_OnDblClick = async function(row, colid) {
    if (colid === "FL_NM") {
        scwin.filedown(row);
    } else if (colid === "DEL") {
        await scwin.delete(row);
    }
};

/**
 * @method
 * @name img_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_close_onclick = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name gform_onload
 * @description 패널라운드 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.getParentValue();
    const sbmOptions = {
        id : "sbm_dts_Pnlt_Input",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Pnlt_Input=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    fn_Search();
};

/**
 * @method
 * @name trs_Pnlt_Input_OnFail
 * @description Pnlt Input On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Pnlt_Input_OnFail = async function() {
    await $c.win.alert('trs_Pnlt_Input.OnFail() :' + trs_Pnlt_Input.ErrorMsg);
};

/**
 * @method
 * @name trs_Pnlt_Input_OnSuccess
 * @description Pnlt Input On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Pnlt_Input_OnSuccess = async function() {
    await $c.win.alert("처리완료");

    // 화면 RELOAD
    fn_Search();
    // dataset 초기화
    dts_Pnlt_Input.removeAll();
};
